using HoTroDuLich.Web.Data;
using HoTroDuLich.Web.Domain;
using Microsoft.EntityFrameworkCore;
namespace HoTroDuLich.Web.Services;

public sealed class NhacDenHanDinhChiService(IServiceScopeFactory scopes,IDongHo clock,ILogger<NhacDenHanDinhChiService> logger):BackgroundService {
 protected override async Task ExecuteAsync(CancellationToken token){DateOnly? checkedDay=null;using var timer=new PeriodicTimer(TimeSpan.FromMinutes(1));do{var local=clock.DoiSangGioVN(clock.BayGioUtc);if(local.Hour>=7&&checkedDay!=clock.HomNay){try{await KiemTraAsync(token);checkedDay=clock.HomNay;}catch(Exception e)when(!token.IsCancellationRequested){logger.LogError(e,"Không thể tạo nhắc hạn đình chỉ");using var failureScope=scopes.CreateScope();try{var db=failureScope.ServiceProvider.GetRequiredService<AppDbContext>();db.NhatKyThaoTac.Add(new(){LoaiSuKien="LoiHeThong",DoiTuong="NhacDenHanDinhChi",TrangThaiSau="ThatBai",LyDo="Không thể tạo nhắc hạn; sẽ kiểm tra lại ở lần chạy sau."});await db.SaveChangesAsync(token);}catch(Exception logError)when(!token.IsCancellationRequested){logger.LogError(logError,"Không thể ghi nhật ký công việc nền");}}}}while(await timer.WaitForNextTickAsync(token));}
 public async Task KiemTraAsync(CancellationToken token=default){using var scope=scopes.CreateScope();var db=scope.ServiceProvider.GetRequiredService<AppDbContext>();var due=await db.QuyetDinhQuyenHoatDong.Where(d=>d.TrangThaiSau==TrangThaiQuyenHoatDong.TamDinhChi&&d.ThoiHan<=clock.HomNay&&db.NhaCungCapDichVu.Any(p=>p.MaNhaCungCap==d.MaNhaCungCap&&p.TrangThaiQuyenHoatDong==TrangThaiQuyenHoatDong.TamDinhChi)&&!db.QuyetDinhQuyenHoatDong.Any(newer=>newer.MaNhaCungCap==d.MaNhaCungCap&&newer.MaQuyetDinh>d.MaQuyetDinh)).ToListAsync(token);var admins=await db.TaiKhoan.Where(a=>a.VaiTro==VaiTro.QUAN_TRI_VIEN&&a.TrangThai==TrangThaiTaiKhoan.HoatDong).Select(a=>a.MaTaiKhoan).ToListAsync(token);foreach(var decision in due){var text=$"Đến hạn xem xét đình chỉ nhà cung cấp #{decision.MaNhaCungCap} (quyết định #{decision.MaQuyetDinh})";foreach(var admin in admins)if(!await db.ThongBao.AnyAsync(n=>n.MaNguoiNhan==admin&&n.LoaiThongBao=="DenHanDinhChi"&&n.NoiDung==text,token))db.ThongBao.Add(new(){MaNguoiNhan=admin,LoaiThongBao="DenHanDinhChi",NoiDung=text,DuongDan="/quan-tri/quyen-hoat-dong/xem-chi-tiet/"+decision.MaNhaCungCap});}await db.SaveChangesAsync(token);}
}

